    splitPart(context, id + "split1", { "splitType" : SplitType.FACE, "faceTargets" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 15, 12) * millimeter), "faceTools" : qOwnedByBody(qBodyType(qCreatedBy(id + "cut", EntityType.BODY), BodyType.WIRE), EntityType.EDGE) });
}

// cplane: tangent to a cylinder, parallel to a plane
export function c016(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    opPlane(context, id + "ref", { "plane" : plane(vector(30, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)), "width" : 100 * millimeter, "height" : 100 * millimeter });
    cPlane(context, id + "plane1", { "cplaneType" : CPlaneType.TANGENT_PLANE, "entities" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(10, 0, 10) * millimeter), qCreatedBy(id + "ref", EntityType.FACE)]), "width" : 60 * millimeter, "height" : 40 * millimeter });
}

// composite-part: two blocks made one composite part
export function c017(context is Context, id is Id)
{
    const aSketch = newSketchOnPlane(context, id + "aSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(aSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(aSketch);
    extrude(context, id + "a", { "entities" : qSketchRegion(id + "aSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const bSketch = newSketchOnPlane(context, id + "bSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(bSketch, "rect1", { "firstCorner" : vector(20, 0) * millimeter, "secondCorner" : vector(30, 10) * millimeter });
    skSolve(bSketch);
    extrude(context, id + "b", { "entities" : qSketchRegion(id + "bSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    compositePart(context, id + "composite1", { "bodies" : qUnion([qBodyType(qCreatedBy(id + "a", EntityType.BODY), BodyType.SOLID), qBodyType(qCreatedBy(id + "b", EntityType.BODY), BodyType.SOLID)]), "closed" : true });
    return { "composites" : evaluateQueryCount(context, qBodyType(qEverything(EntityType.BODY), BodyType.COMPOSITE)) };
}

// revolve: a thin revolve of a line
export function c018(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(s1, "line1", { "start" : vector(10, 0) * millimeter, "end" : vector(20, 15) * millimeter });
    skSolve(s1);
    const axis1 = newSketchOnPlane(context, id + "axis1", { "sketchPlane" : plane(vector(0, 0, -50) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis1, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skSolve(axis1);
    revolve(context, id + "revolve1", { "bodyType" : ExtendedToolBodyType.THIN, "wallShape" : qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "axis" : qCreatedBy(id + "axis1", EntityType.EDGE), "midplane" : false, "thickness1" : 2 * millimeter, "thickness2" : 0 * millimeter, "flipWall" : false });
}

// sweep: a thin sweep of a line along an arc
export function c019(context is Context, id is Id)
{
    const profile = newSketchOnPlane(context, id + "profile", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skLineSegment(profile, "line1", { "start" : vector(-4, 0) * millimeter, "end" : vector(4, 0) * millimeter });
    skSolve(profile);
    const path = newSketchOnPlane(context, id + "path", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skArc(path, "arc1", { "start" : vector(0, 0) * millimeter, "mid" : vector(20, 8.28427) * millimeter, "end" : vector(28.28427, 28.28427) * millimeter });
    skSolve(path);
    sweep(context, id + "sweep1", { "bodyType" : ExtendedToolBodyType.THIN, "profiles" : qNothing(), "wallShape" : qOwnedByBody(qBodyType(qCreatedBy(id + "profile", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "path" : qOwnedByBody(qBodyType(qCreatedBy(id + "path", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "midplane" : false, "thickness1" : 1.5 * millimeter, "thickness2" : 0 * millimeter, "flipWall" : false, "trimEnds" : false });
}

// loft: a surface loft between two arcs
export function c020(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skArc(s1, "arc1", { "start" : vector(0, 0) * millimeter, "mid" : vector(15, 6) * millimeter, "end" : vector(30, 0) * millimeter });
    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 20, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skArc(s2, "arc1", { "start" : vector(0, 0) * millimeter, "mid" : vector(15, 6) * millimeter, "end" : vector(30, 0) * millimeter });
    skSolve(s2);
    loft(context, id + "loft1", { "bodyType" : ExtendedToolBodyType.SURFACE, "wireProfilesArray" : [{ "wireProfileEntities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]) }, { "wireProfileEntities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "s2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]) }] });
}

// revolve: up to a face
export function c021(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, -20) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(-40, 5) * millimeter, "secondCorner" : vector(40, 15) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 40 * millimeter });
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skRectangle(s1, "rect1", { "firstCorner" : vector(10, -5) * millimeter, "secondCorner" : vector(20, 5) * millimeter });
    skSolve(s1);
    const axis1 = newSketchOnPlane(context, id + "axis1", { "sketchPlane" : plane(vector(0, 0, -50) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis1, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skSolve(axis1);
    revolve(context, id + "revolve1", { "entities" : qSketchRegion(id + "s1"), "axis" : qCreatedBy(id + "axis1", EntityType.EDGE), "fullRevolve" : false, "endBound" : RevolveBoundingType.UP_TO_SURFACE, "endBoundEntityFace" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(0, 5, 0) * millimeter) });
}
